using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Overclock {
 sealed class SidebarLabel:Label {
  public int LogicalHeight=25;
  protected override void OnPaint(PaintEventArgs e){TextRenderer.DrawText(e.Graphics,Text,Font,ClientRectangle,ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding|TextFormatFlags.EndEllipsis);}
 }
 sealed class SidebarPanel:Panel {
  public const int LogicalWidth=264,LogicalPadding=16,ButtonHeight=48,ButtonGap=10,LabelLeft=52;
  readonly DarkScrollBar scroll=new DarkScrollBar();bool arranging;int menuBottom;internal float FixtureScale;
  public SidebarPanel(){DoubleBuffered=true;AutoScroll=false;BackColor=Color.FromArgb(10,10,12);Controls.Add(scroll);scroll.ValueChanged+=(s,e)=>PerformLayout();}
  public float LayoutScale{get{if(FixtureScale>0)return FixtureScale;using(var g=CreateGraphics())return g.DpiX/96;}}
  public static int Pixels(float logical,float scale){return (int)Math.Round(logical*scale,MidpointRounding.AwayFromZero);}
  protected override void OnControlAdded(ControlEventArgs e){base.OnControlAdded(e);if(e.Control==scroll)return;e.Control.Margin=Padding.Empty;e.Control.BackColor=BackColor;e.Control.GotFocus+=(s,args)=>EnsureVisible(e.Control);e.Control.MouseWheel+=(s,args)=>{scroll.Wheel(args.Delta);var handled=args as HandledMouseEventArgs;if(handled!=null)handled.Handled=true;};PerformLayout();}
  protected override void OnDpiChangedAfterParent(EventArgs e){base.OnDpiChangedAfterParent(e);PerformLayout();Invalidate();}
  protected override void OnMouseWheel(MouseEventArgs e){scroll.Wheel(e.Delta);var handled=e as HandledMouseEventArgs;if(handled!=null)handled.Handled=true;}
  protected override void OnLayout(LayoutEventArgs e){if(arranging)return;arranging=true;try{float scale=LayoutScale;int wanted=Pixels(LogicalWidth,scale);if(Width!=wanted)Width=wanted;int pad=Pixels(LogicalPadding,scale),gap=Pixels(ButtonGap,scale),y=Pixels(25,scale);var items=Controls.Cast<Control>().Where(c=>c!=scroll).ToArray();foreach(Control item in items){int height=item is Button?Pixels(ButtonHeight,scale):item is BrandLogo?Pixels(58,scale):Pixels(item is SidebarLabel?((SidebarLabel)item).LogicalHeight:25,scale);item.SetBounds(pad,y-scroll.Value,wanted-pad*2,height);var button=item as ModernButton;if(button!=null)button.NavigationScale=scale;y+=height;if(item is Button||item is SidebarLabel&&((SidebarLabel)item).LogicalHeight==48)y+=gap;}
   menuBottom=y-gap;scroll.Range(menuBottom+pad,Height,scroll.Value);scroll.SmallStep=Pixels(24,scale);scroll.SetBounds(wanted-Pixels(14,scale),Pixels(8,scale),Pixels(12,scale),Math.Max(1,Height-Pixels(16,scale)));scroll.Visible=scroll.Maximum>0;scroll.TabIndex=100;scroll.BringToFront();int currentY=Pixels(25,scale);foreach(Control item in items){item.Top=currentY-scroll.Value;currentY+=item.Height;if(item is Button||item is SidebarLabel&&((SidebarLabel)item).LogicalHeight==48)currentY+=gap;}Invalidate();
  }finally{arranging=false;}base.OnLayout(e);}
  void EnsureVisible(Control item){if(item.Top<0)scroll.Value+=item.Top;else if(item.Bottom>Height)scroll.Value+=item.Bottom-Height;}
  internal void ScrollToEnd(){scroll.Value=scroll.Maximum;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;float scale=LayoutScale;int start=Math.Max(menuBottom-scroll.Value+Pixels(24,scale),Height-Pixels(330,scale));if(start<Height){var state=g.Save();g.SetClip(new Rectangle(0,Math.Max(0,start),Width,Height-Math.Max(0,start)));using(var brush=new LinearGradientBrush(new Rectangle(0,start,Math.Max(1,Width),Math.Max(1,Height-start)),Color.FromArgb(30,3,8),Color.FromArgb(130,5,20),45))g.FillPolygon(brush,new[]{new Point(0,Height-Pixels(30,scale)),new Point(0,Height-Pixels(98,scale)),new Point(Width,Height-Pixels(390,scale)),new Point(Width,Height-Pixels(312,scale))});using(var brush=new SolidBrush(Theme.PrimaryHover))g.FillPolygon(brush,new[]{new Point(0,Height),new Point(Pixels(28,scale),Height),new Point(Width,Height-Pixels(260,scale)),new Point(Width,Height-Pixels(292,scale))});using(var pen=new Pen(Theme.Accent))g.DrawLine(pen,0,Height-Pixels(98,scale),Width,Height-Pixels(390,scale));g.Restore(state);}using(var pen=new Pen(Theme.Line))g.DrawLine(pen,Width-1,0,Width-1,Height);}
  internal void AssertLayout(){float s=LayoutScale;int pad=Pixels(LogicalPadding,s);if(Width!=Pixels(LogicalWidth,s))throw new Exception("Sidebar width is incorrect");var items=Controls.Cast<Control>().Where(c=>c!=scroll).ToArray();foreach(var c in items)if(c.Left!=pad||c.Right!=Width-pad)throw new Exception("Sidebar horizontal alignment: "+c.Text);var buttons=items.OfType<ModernButton>().ToArray();for(int i=0;i<buttons.Length;i++){var b=buttons[i];if(b.Height!=Pixels(ButtonHeight,s)||b.Width!=Width-pad*2)throw new Exception("Navigation size: "+b.Text);if(i>0&&b.Top-buttons[i-1].Bottom!=Pixels(ButtonGap,s))throw new Exception("Navigation spacing: "+b.Text);int labelWidth=b.Width-Pixels(LabelLeft+12,s);if(TextRenderer.MeasureText(b.Text,b.Font,Size.Empty,TextFormatFlags.NoPadding).Width>labelWidth)throw new Exception("Navigation text clipped: "+b.Text);}}
  internal static void Fixtures(string folder){foreach(float scale in new[]{1f,1.25f,1.5f})foreach(int logicalHeight in new[]{560,720,992})using(var side=new SidebarPanel{FixtureScale=scale,Height=Pixels(logicalHeight,scale)}){side.Controls.Add(new BrandLogo());side.Controls.Add(new SidebarLabel{LogicalHeight=48,Text="LAYOUT FIXTURE / "+(scale*100)+"%",Font=new Font("Segoe UI",10*scale),ForeColor=Theme.Muted});foreach(string name in new[]{"Overview","Hardware","Storage tests","GPU stress","Reports","RGB Studio","Display Studio","Settings","Logs","Compact monitor"})side.Controls.Add(new ModernButton{Text=name,NavGlyph=name,Font=new Font("Segoe UI",12*scale)});side.CreateControl();side.PerformLayout();side.AssertLayout();using(var bitmap=new Bitmap(side.Width,side.Height)){side.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(folder,"Sidebar-"+(scale*100)+"percent-"+logicalHeight+"-fixture.png"));}side.ScrollToEnd();side.AssertLayout();var last=side.Controls.OfType<ModernButton>().Last();if(last.Bottom>side.Height)throw new Exception("Last navigation item is clipped after scrolling");}}
 }
 sealed partial class MainWindow {
  public void BeginSidebarTest(string folder){Directory.CreateDirectory(folder);Shown+=async(sender,args)=>{var log=new StringBuilder();try{await Task.Delay(8000);WindowState=FormWindowState.Normal;TopMost=true;foreach(var dimensions in new[]{new Size(1586,992),new Size(1280,720),new Size(900,600)}){ClientSize=dimensions;PerformLayout();navBar.PerformLayout();await Task.Delay(300);navBar.AssertLayout();var content=Controls.Cast<Control>().First(c=>c!=navBar&&c.Dock==DockStyle.Fill);if(content.Left!=navBar.Right||content.Right!=ClientSize.Width)throw new Exception("Main content does not fill the remaining width");foreach(var tile in tiles.Values){var tipField=typeof(MetricCard).GetField("deviceTip",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var tip=tipField==null?null:tipField.GetValue(tile) as ToolTip;if(tip!=null)tip.Hide(tile);}BringToFront();Activate();Refresh();Application.DoEvents();using(var bitmap=new Bitmap(ClientSize.Width,ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(PointToScreen(Point.Empty),Point.Empty,ClientSize);bitmap.Save(Path.Combine(folder,"Overview-"+dimensions.Width+"x"+dimensions.Height+"-actual.png"));}log.AppendLine("PASS actual window "+dimensions+": sidebar padding/width, equal buttons, text fit, spacing and remaining content width");}SidebarPanel.Fixtures(folder);log.AppendLine("PASS sidebar layout fixtures at 100/125/150 percent and 560/720/992 logical heights; scrolling reaches last item. These fixtures are not monitor-DPI captures.");File.WriteAllText(Path.Combine(folder,"results.txt"),log.ToString());}catch(Exception error){Environment.ExitCode=1;log.AppendLine("FAIL "+error);File.WriteAllText(Path.Combine(folder,"results.txt"),log.ToString());}finally{Close();}};}
 }
}
